/* @lc app=leetcode id=3715 lang=kotlin */ class Solution { fun sf(x: Int): Int = (2..Math.sqrt(x.toDouble()).toInt()).fold(x to 1) { (r, acc), p -> generateSequence(r to 0) { (y, c) -> if (y % p == 0) y / p to c + 1 else null }.last().let { (y, c) -> y to (if (c % 2 == 1) acc * p else acc) } }.let { (r, acc) -> acc * r } fun sumOfAncestors(n: Int, edges: Array<IntArray>, nums: IntArray): Long = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> nums.map { sf(it) }.let { s -> IntArray(100001).let { cnt -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> java.util.ArrayDeque<Int>().also { it.addFirst(0) }.let { st -> generateSequence { st.pollFirst() }.sumOf { e -> if (e >= 0) cnt[s[e]].toLong().also { cnt[s[e]]++ }.also { st.addFirst(e.inv()) }.also { g[e].orEmpty().filter { par[it] == -1 }.forEach { c -> par.set(c, e).also { st.addFirst(c) } } } else cnt.set(s[e.inv()], cnt[s[e.inv()]] - 1).let { 0L } } } } } } } }